def score(genome):
    predicted = fit_genome(genome)
    return float(np.mean((predicted[validation] - series[targets[validation]]) ** 2))
population = [{'lag': lag, 'alpha': alpha}
              for lag in [2, 4, 8] for alpha in [0.01, 1.0]]
history = []
for generation in range(4):
    losses = np.array([score(genome) for genome in population])
    ranked = np.argsort(losses, kind='stable')
    parents = [dict(population[i]) for i in ranked[:2]]
    history.append(float(losses[ranked[0]]))
    population = [dict(parent) for parent in parents]
    for _ in range(4):
        child = {'lag': parents[int(rng.integers(2))]['lag'],
                 'alpha': parents[int(rng.integers(2))]['alpha']}
        if rng.random() < 0.5:
            child['lag'] = int(rng.choice([2, 4, 8]))
        else:
            child['alpha'] = float(rng.choice([0.01, 0.1, 1.0]))
        population.append(child)
assert np.argsort([0.2, 0.2, 0.3], kind='stable')[:2].tolist() == [0, 1]
assert (np.diff(history) <= 1e-12).all()
print('Лучшая validation MSE по поколениям:', np.round(history, 5))
